import React, { useCallback, useEffect, useRef, useState } from 'react';
import { AlertCircle, Loader2, RefreshCw, ShieldCheck } from 'lucide-react';
import { supabase } from '../lib/supabase';

type HCaptchaApi = {
  render: (container: HTMLElement, options: Record<string, unknown>) => string;
  reset: (widgetId?: string) => void;
  remove?: (widgetId: string) => void;
};

declare global {
  interface Window {
    hcaptcha?: HCaptchaApi;
  }
}

interface WerseeCaptchaProps {
  onVerify: (token: string) => void;
  onExpire: () => void;
  onError?: (message: string) => void;
}

const SCRIPT_ID = 'wersee-hcaptcha-script';

const loadHCaptcha = () => new Promise<HCaptchaApi>((resolve, reject) => {
  if (window.hcaptcha) {
    resolve(window.hcaptcha);
    return;
  }

  const finish = () => window.hcaptcha
    ? resolve(window.hcaptcha)
    : reject(new Error('hCaptcha kon niet worden geladen.'));
  const existing = document.getElementById(SCRIPT_ID) as HTMLScriptElement | null;
  if (existing) {
    existing.addEventListener('load', finish, { once: true });
    existing.addEventListener('error', () => reject(new Error('hCaptcha kon niet worden geladen.')), { once: true });
    return;
  }

  const script = document.createElement('script');
  script.id = SCRIPT_ID;
  script.src = 'https://js.hcaptcha.com/1/api.js?render=explicit&recaptchacompat=off';
  script.async = true;
  script.defer = true;
  script.onload = finish;
  script.onerror = () => reject(new Error('hCaptcha kon niet worden geladen.'));
  document.head.appendChild(script);
});

export const WerseeCaptcha: React.FC<WerseeCaptchaProps> = ({ onVerify, onExpire, onError }) => {
  const containerRef = useRef<HTMLDivElement>(null);
  const widgetIdRef = useRef<string | null>(null);
  const onVerifyRef = useRef(onVerify);
  const onExpireRef = useRef(onExpire);
  const onErrorRef = useRef(onError);
  const [status, setStatus] = useState<'loading' | 'ready' | 'verified' | 'error'>('loading');
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    onVerifyRef.current = onVerify;
    onExpireRef.current = onExpire;
    onErrorRef.current = onError;
  }, [onError, onExpire, onVerify]);

  const fail = useCallback((message: string) => {
    setStatus('error');
    setError(message);
    onExpireRef.current();
    onErrorRef.current?.(message);
  }, []);

  const renderWidget = useCallback(async () => {
    setStatus('loading');
    setError(null);
    onExpireRef.current();

    try {
      const configuredSiteKey = String(import.meta.env.VITE_HCAPTCHA_SITE_KEY || '').trim();
      let siteKey = configuredSiteKey;
      if (!siteKey) {
        const { data, error: configError } = await supabase.functions.invoke('auth-captcha', {
          body: { action: 'config' },
        });
        if (configError) throw configError;
        siteKey = String(data?.siteKey || '').trim();
      }
      if (!siteKey) throw new Error('De beveiligingscontrole is niet geconfigureerd.');

      const hcaptcha = await loadHCaptcha();
      if (!containerRef.current) return;
      if (widgetIdRef.current && hcaptcha.remove) hcaptcha.remove(widgetIdRef.current);
      containerRef.current.replaceChildren();
      widgetIdRef.current = hcaptcha.render(containerRef.current, {
        sitekey: siteKey,
        theme: 'dark',
        size: 'normal',
        callback: (token: string) => {
          setStatus('verified');
          setError(null);
          onVerifyRef.current(token);
        },
        'expired-callback': () => {
          setStatus('ready');
          onExpireRef.current();
        },
        'chalexpired-callback': () => {
          setStatus('ready');
          onExpireRef.current();
        },
        'error-callback': () => fail('De beveiligingscontrole kon niet worden voltooid. Probeer het opnieuw.'),
      });
      setStatus('ready');
    } catch {
      fail('De beveiligingscontrole is tijdelijk niet beschikbaar. Probeer het opnieuw.');
    }
  }, [fail]);

  useEffect(() => {
    void renderWidget();
    return () => {
      if (widgetIdRef.current && window.hcaptcha?.remove) window.hcaptcha.remove(widgetIdRef.current);
    };
  }, [renderWidget]);

  return (
    <section
      aria-labelledby="captcha-title"
      className="w-full rounded-3xl border border-white/10 bg-white/[0.04] p-4 sm:p-5"
    >
      <div className="mb-4 flex items-start gap-3">
        <span className="flex h-11 w-11 shrink-0 items-center justify-center rounded-xl border border-indigo-400/20 bg-indigo-500/10">
          <ShieldCheck className="h-5 w-5 text-indigo-300" aria-hidden="true" />
        </span>
        <div>
          <h2 id="captcha-title" className="text-sm font-bold text-white">Beveiligingscontrole</h2>
          <p className="mt-1 text-xs leading-5 text-white/55">
            Rond de hCaptcha-controle af. De widget ondersteunt toetsenbord- en audiobediening.
          </p>
        </div>
      </div>

      <div className="flex min-h-[82px] w-full items-center justify-center overflow-x-auto" aria-busy={status === 'loading'}>
        {status === 'loading' && (
          <div className="flex items-center gap-2 text-sm text-white/60" role="status">
            <Loader2 className="h-4 w-4 animate-spin" aria-hidden="true" />
            Beveiligingscontrole laden…
          </div>
        )}
        <div ref={containerRef} className={status === 'loading' ? 'hidden' : 'block'} />
      </div>

      <div className="mt-3 min-h-5 text-center text-xs" aria-live="polite">
        {status === 'verified' && <span className="text-emerald-400">Beveiligingscontrole voltooid.</span>}
        {error && (
          <span className="inline-flex items-center gap-1.5 text-red-400" role="alert">
            <AlertCircle className="h-3.5 w-3.5" aria-hidden="true" />
            {error}
          </span>
        )}
      </div>

      {(status === 'error' || status === 'ready') && (
        <button
          type="button"
          onClick={() => void renderWidget()}
          className="mx-auto mt-2 flex min-h-11 items-center gap-2 rounded-xl px-4 text-xs font-bold text-white/60 transition hover:bg-white/5 hover:text-white focus:outline-none focus:ring-2 focus:ring-indigo-400/60"
        >
          <RefreshCw className="h-4 w-4" aria-hidden="true" />
          Nieuwe controle laden
        </button>
      )}
    </section>
  );
};
